import{_ as o,o as t,c as a,a5 as s}from"./chunks/framework.DJo0M80U.js";const q=JSON.parse('{"title":"equals方法和==操作符","description":"基本数据类型和引用数据类型 在Java中，数据类型分为基本数据类型（primitive types）和引用数据类型（reference types）。 基本数据类型：byte, short, int, long, float, double, char, boolean 引用数据。","frontmatter":{"title":"equals方法和==操作符","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","Java 面试"],"description":"基本数据类型和引用数据类型 在Java中，数据类型分为基本数据类型（primitive types）和引用数据类型（reference types）。 基本数据类型：byte, short, int, long, float, double, char, boolean 引用数据。","sidebarWeight":3,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/java/基础/`equals`方法和`==`操作符.md"},"headers":[],"relativePath":"posts/前端面试与实战/04-Java 面试/基础/equals方法和==操作符.md","filePath":"posts/前端面试与实战/04-Java 面试/基础/equals方法和==操作符.md"}'),l={name:"posts/前端面试与实战/04-Java 面试/基础/equals方法和==操作符.md"};function n(i,e,r,u,c,d){return t(),a("div",null,[...e[0]||(e[0]=[s('<div><h1 id="equals方法和-操作符" tabindex="-1">equals方法和==操作符 <a class="header-anchor" href="#equals方法和-操作符" aria-label="Permalink to &quot;equals方法和==操作符&quot;">​</a></h1><blockquote><p>本节目标：理解“equals方法和==操作符”的核心思路，并能把它用于实际开发或面试表达。 基本数据类型和引用数据类型 在Java中，数据类型分为基本数据类型（primitive types）和引用数据类型（reference types）。</p></blockquote><ul><li>基本数据类型：byte, short, int, long, float, double, char, boolean</li><li>引用数据类型：所有的对象类型，包括数组、类和接口类型</li></ul><p><code>==</code>操作符</p><ul><li>基本数据类型：<code>==</code>用于比较两个基本数据类型的值是否相等。例如： int a = 5; int b = 5; if (a == b) { System.out.println(&quot;a and b are equal&quot;); }</li><li>引用数据类型：<code>==</code>用于比较两个引用是否指向同一个对象。例如： String s1 = new String(&quot;hello&quot;); String s2 = new String(&quot;hello&quot;); if (s1 == s2) { System.out.println(&quot;s1 and s2 are the same object&quot;); } else { System.out.println(&quot;s1 and s2 are different objects&quot;); }</li></ul><p><code>equals</code>方法</p><ul><li><code>equals</code>方法是<code>Object</code>类中的一个方法，默认实现是比较对象的引用，即<code>==</code>。如果没有重写<code>equals</code>方法，比较的是对象的引用，而不是内容。</li><li>一旦重写了<code>equals</code>方法，<code>equals</code>方法可以用于比较对象的内容。例如，<code>String</code>类重写了<code>equals</code>方法，用于比较字符串的内容是否相等。 重写<code>equals</code>方法的示例 public class Person { private String name; private int age; public Person(String name, int age) { this.name = name; this.age = age; } @Override public boolean equals(Object obj) { if (this == obj) return true; if (obj == null || getClass() != obj.getClass()) return false; Person person = (Person) obj; return age == person.age &amp;&amp; Objects.equals(name, person.name); } @Override public int hashCode() { return Objects.hash(name, age); } public static void main(String[] args) { Person p1 = new Person(&quot;John&quot;, 30); Person p2 = new Person(&quot;John&quot;, 30); System.out.println(p1.equals(p2)); // true } }</li></ul><p>总结</p><ul><li><code>==</code>操作符：可以用于比较基本数据类型和引用数据类型。对于基本数据类型，比较的是值；对于引用数据类型，比较的是引用（即对象的地址）。</li><li><code>equals</code>方法：用于比较对象的内容。默认实现是比较对象的引用（即<code>==</code>），需要重写以比较对象的内容。<code>equals</code>不能用于比较基本数据类型，因为基本数据类型不是对象。</li></ul></div>',1)])])}const b=o(l,[["render",n]]);export{q as __pageData,b as default};
